function db(){return new Promise((resolve,reject)=>{const q=indexedDB.open(DB_NAME,1);q.onupgradeneeded=()=>q.result.createObjectStore(STORE);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
function migrateState(){state=state&&typeof state==='object'?state:{};state.jobs=Array.isArray(state.jobs)?state.jobs:[];state.settings=state.settings||{};state.settings.business=state.settings.business||'Niko Residential Holdings';state.settings.legal=state.settings.legal||'Amr and Nhi LLC';if(!state.settings.phone||state.settings.phone==='543-212-5883')state.settings.phone='513-212-5883';state.settings.email=state.settings.email||'daraghmehamr1@gmail.com';state.settings.address=state.settings.address||'';state.settings.website=state.settings.website||'https://nikoresidentialholdings.com';state.counter=Number(state.counter||1);state.jobs.forEach(j=>{j.photoUsePermission=j.photoUsePermission||'Documentation only';j.appointments=Array.isArray(j.appointments)?j.appointments:[];j.beforePhotos=Array.isArray(j.beforePhotos)?j.beforePhotos:[];j.afterPhotos=Array.isArray(j.afterPhotos)?j.afterPhotos:[];j.receiptPhotos=Array.isArray(j.receiptPhotos)?j.receiptPhotos:[]});return state}
async function loadState(){try{const d=await db();const tx=d.transaction(STORE,'readonly');const req=tx.objectStore(STORE).get('app');const saved=await new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)});if(saved)state=saved}catch(e){console.error(e)}migrateState();hydrateSettings();renderDashboard();updateDocSelect()}
async function persist(){try{const d=await db();const tx=d.transaction(STORE,'readwrite');tx.objectStore(STORE).put(state,'app');await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});$('#autosaveState').textContent='Saved';return true}catch(e){console.error(e);toast('Could not save on this device');return false}}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._x);t._x=setTimeout(()=>t.classList.remove('show'),2400)}
function money(v){return (Number(v)||0).toLocaleString('en-US',{style:'currency',currency:'USD'})}
function dateLabel(v){if(!v)return'';const d=/^\d{4}-\d{2}-\d{2}$/.test(String(v))?new Date(`${v}T12:00:00`):new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function jobNumber(j){return Number(String(j?.quoteNumber||'').match(/\d+/)?.[0]||0)}
function nextNumberValue(){const used=new Set([...(state.jobs||[]).map(jobNumber),...(state.retiredNumbers||[]).map(Number)]);let n=1;while(used.has(n))n++;state.counter=n;return n}
function nextNum(){return String(nextNumberValue()).padStart(4,'0')}
function blankJob(){const n=nextNum(),today=new Date().toISOString().slice(0,10);return{id:crypto.randomUUID(),createdAt:Date.now(),updatedAt:Date.now(),customerName:'',customerPhone:'',customerEmail:'',status:'Draft quote',billingAddress:'',projectAddress:'',quoteNumber:`Q-${n}`,contractNumber:`C-${n}`,invoiceNumber:`I-${n}`,description:'',items:[{id:crypto.randomUUID(),done:false,category:'Labor',description:'',qty:1,rate:0}],tax:0,discount:0,materials:'',cleanup:'',quoteDate:today,contractDate:'',startDate:'',completionDate:'',validThrough:'',deposit:0,paymentDue:'At completion',paymentMethod:'',paymentReference:'',workDays:'',permitsBy:'',workerType:'In-house — Amr Daraghmeh',workerName:'Amr Daraghmeh',workerCompany:'Niko Residential Holdings',workerContact:'',workerTrade:'',workerLicense:'',workerInsurance:'Not applicable',freelancerName:'',freelancerCompany:'',freelancerContact:'',freelancerScope:'',freelancerPrice:0,freelancerPaymentTerms:'After customer acceptance of completed work',freelancerStart:'',freelancerCompletion:'',freelancerDocuments:'Not collected',beforePhotos:[],afterPhotos:[],receiptPhotos:[],photoUsePermission:'Documentation only',appointments:[],completedDescription:'',laborTotal:'',materialTotal:'',otherCost:'',paymentsReceived:0,paymentDate:'',receiptDate:''}}
function totals(j){const items=j.items||[],labor=items.filter(x=>(x.category||'Labor')==='Labor').reduce((s,x)=>s+(Number(x.qty)||0)*(Number(x.rate)||0),0),materials=items.filter(x=>x.category==='Material').reduce((s,x)=>s+(Number(x.qty)||0)*(Number(x.rate)||0),0),subtotal=labor+materials,quotedTotal=subtotal+(Number(j.tax)||0)-(Number(j.discount)||0),receiptLabor=j.laborTotal===''?labor:Number(j.laborTotal)||0,receiptMaterials=j.materialTotal===''?materials:Number(j.materialTotal)||0,receiptTotal=receiptLabor+receiptMaterials+(Number(j.otherCost)||0),finalTotal=['Completed','Paid'].includes(j.status)&&receiptTotal>0?receiptTotal:quotedTotal,total=finalTotal,due=finalTotal-(Number(j.paymentsReceived)||0);return{labor,materials,subtotal,quotedTotal,total,receiptLabor,receiptMaterials,receiptTotal,finalTotal,due}}
function renderDashboard(filter=''){const jobs=state.jobs.filter(j=>[j.customerName,j.projectAddress,j.quoteNumber,j.contractNumber,j.invoiceNumber].join(' ').toLowerCase().includes(filter.toLowerCase()));$('#statJobs').textContent=state.jobs.length;$('#statOpen').textContent=state.jobs.filter(j=>!['Completed','Paid'].includes(j.status)).length;$('#statValue').textContent=money(state.jobs.reduce((s,j)=>s+totals(j).total,0));$('#statDue').textContent=money(state.jobs.reduce((s,j)=>s+Math.max(0,totals(j).due),0));$('#nextNumber').textContent=nextNum();const list=$('#jobList');list.innerHTML=jobs.map(j=>`<div class="job-row"><div><b>${esc(j.customerName||'Unnamed customer')}</b><small>${esc(j.projectAddress||'No project address')}</small></div><div><b>${esc(j.quoteNumber)}</b><small>${new Date(j.updatedAt).toLocaleDateString()}</small></div><span class="status-chip">${esc(j.status)}</span><div><b>${money(totals(j).total)}</b><small>${money(totals(j).due)} due</small></div><button class="open-job" data-id="${j.id}" aria-label="Open ${esc(j.customerName||'job')}">›</button><button class="job-delete" data-id="${j.id}" aria-label="Delete ${esc(j.quoteNumber)}">×</button></div>`).join('');$('#emptyJobs').classList.toggle('hidden',state.jobs.length>0);$$('.open-job').forEach(b=>b.onclick=()=>openJob(b.dataset.id));$$('.job-delete').forEach(b=>b.onclick=()=>deleteJobById(b.dataset.id))}
function switchView(name){$$('.view').forEach(v=>v.classList.remove('active'));$(`#${name}View`).classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#viewTitle').textContent={dashboard:'Project dashboard',editor:'Job workspace',leads:'Quote requests',schedule:'Schedule',publicProjects:'Public projects',documents:'Print center',policies:'Policies and terms',settings:'Settings'}[name]||'Niko Project Manager';$('.sidebar').classList.remove('open');if(name==='documents'){updateDocSelect();renderPreview()}if(window.nikoPortalView)window.nikoPortalView(name)}
function createJob(){const j=blankJob();state.jobs.unshift(j);state.counter++;state.currentId=j.id;persist();openJob(j.id);toast('New job created')}
function currentJob(){return state.jobs.find(j=>j.id===state.currentId)}
function openJob(id){state.currentId=id;activeStep=1;fillForm(currentJob());switchView('editor');setStep(1)}
function fillForm(j){if(!j)return;const form=$('#jobForm');Object.entries(j).forEach(([k,v])=>{const el=form.elements[k];if(!el||['items','beforePhotos','afterPhotos','receiptPhotos'].includes(k))return;if(el instanceof RadioNodeList){[...el].forEach(x=>x.checked=x.value===v)}else el.value=v??''});$('#jobHeading').textContent=j.customerName||'New project';$('#jobNumbers').textContent=`${j.quoteNumber} · ${j.contractNumber} · ${j.invoiceNumber}`;$('#jobStatusBadge').textContent=j.status;renderItems(j);renderPhotos(j,'beforePhotos','#beforeGrid');renderPhotos(j,'afterPhotos','#afterGrid');renderPhotos(j,'receiptPhotos','#receiptGrid');calcTotals()}
function collectForm(){const j=currentJob();if(!j)return null;const fd=new FormData($('#jobForm'));for(const [k,v] of fd.entries())if(!['beforePhotos','afterPhotos','receiptPhotos'].includes(k))j[k]=v;j.updatedAt=Date.now();j.items=$$('.line-item').map(r=>({id:r.dataset.id,done:$('[data-f="done"]',r).checked,description:$('[data-f="description"]',r).value,qty:$('[data-f="qty"]',r).value,rate:$('[data-f="rate"]',r).value}));$('#jobHeading').textContent=j.customerName||'New project';$('#jobNumbers').textContent=`${j.quoteNumber} · ${j.contractNumber} · ${j.invoiceNumber}`;$('#jobStatusBadge').textContent=j.status;return j}
function autosave(){clearTimeout(saveTimer);$('#autosaveState').textContent='Saving…';saveTimer=setTimeout(async()=>{collectForm();await persist();renderDashboard();updateDocSelect()},400)}
function renderItems(j){$('#lineItems').innerHTML=(j.items||[]).map(x=>`<div class="line-item" data-id="${x.id}"><input data-f="done" type="checkbox" ${x.done?'checked':''} aria-label="Completed"><input data-f="description" value="${esc(x.description)}" placeholder="Work or material"><input data-f="qty" type="number" step="0.01" value="${esc(x.qty)}"><input data-f="rate" type="number" step="0.01" value="${esc(x.rate)}"><strong data-amount>${money((Number(x.qty)||0)*(Number(x.rate)||0))}</strong><button type="button" class="remove-item" aria-label="Remove item">×</button></div>`).join('');$$('.remove-item').forEach(b=>b.onclick=()=>{b.closest('.line-item').remove();calcTotals();autosave()})}
function addItem(){const j=currentJob();collectForm();j.items.push({id:crypto.randomUUID(),done:false,description:'',qty:1,rate:0});renderItems(j);autosave()}
function calcTotals(){const rows=$$('.line-item');let sub=0;rows.forEach(r=>{const amount=(Number($('[data-f="qty"]',r).value)||0)*(Number($('[data-f="rate"]',r).value)||0);$('[data-amount]',r).textContent=money(amount);sub+=amount});const total=sub+(Number($('#jobForm').elements.tax.value)||0)-(Number($('#jobForm').elements.discount.value)||0),freelancer=Number($('#jobForm').elements.freelancerPrice?.value)||0;$('#subtotal').textContent=money(sub);$('#grandTotal').textContent=money(total);if($('#customerContractTotal'))$('#customerContractTotal').textContent=money(total);if($('#freelancerCostTotal'))$('#freelancerCostTotal').textContent=money(freelancer);if($('#grossDifference'))$('#grossDifference').textContent=money(total-freelancer)}
function setStep(n){activeStep=Math.max(1,Math.min(5,n));$$('.step').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===activeStep));$$('.form-step').forEach(p=>p.classList.toggle('active',Number(p.dataset.stepPanel)===activeStep));$('#prevStep').disabled=activeStep===1;$('#nextStep').textContent=activeStep===5?'Save & view documents':'Continue';window.scrollTo({top:0,behavior:'smooth'})}
async function imageData(file){if(!file.type.startsWith('image/'))return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});const source=await createImageBitmap(file),max=1600,scale=Math.min(1,max/Math.max(source.width,source.height)),canvas=document.createElement('canvas');canvas.width=Math.round(source.width*scale);canvas.height=Math.round(source.height*scale);canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);source.close();return canvas.toDataURL('image/jpeg',.78)}
async function filesToPhotos(files,key){const j=currentJob();for(const file of files){if(file.size>8*1024*1024){toast(`${file.name} is too large`);continue}const data=await imageData(file);j[key].push({id:crypto.randomUUID(),name:file.name,type:file.type.startsWith('image/')?'image/jpeg':file.type,data,caption:''})}await persist();renderPhotos(j,key,{beforePhotos:'#beforeGrid',afterPhotos:'#afterGrid',receiptPhotos:'#receiptGrid'}[key]);toast('Files added and optimized')}
function renderPhotos(j,key,target){$(target).innerHTML=(j[key]||[]).map(p=>`<div class="photo-card" data-id="${p.id}">${p.type.startsWith('image/')?`<img src="${p.data||''}" alt="${esc(p.caption||p.name)}">`:`<div style="height:145px;display:grid;place-items:center;background:#edf2f4;font-weight:800">PDF receipt</div>`}<button type="button" aria-label="Remove">×</button><footer><input value="${esc(p.caption)}" placeholder="Area or note"></footer></div>`).join('');$$(`${target} .photo-card`).forEach(c=>{$('button',c).onclick=async()=>{const removed=j[key].find(p=>p.id===c.dataset.id);j[key]=j[key].filter(p=>p.id!==c.dataset.id);if(window.nikoDeleteRemoteFile)await window.nikoDeleteRemoteFile(removed);persist();renderPhotos(j,key,target)};$('input',c).oninput=e=>{const p=j[key].find(p=>p.id===c.dataset.id);p.caption=e.target.value;persist()}})}
async function deleteCurrent(){const j=currentJob();if(!j||!confirm(`Delete ${j.customerName||j.quoteNumber}? This cannot be undone.`))return;if(window.nikoDeleteRemoteFiles)await window.nikoDeleteRemoteFiles(j);state.jobs=state.jobs.filter(x=>x.id!==j.id);state.currentId=null;persist();renderDashboard();switchView('dashboard');toast('Job deleted')}
async function deleteJobById(id){const j=state.jobs.find(x=>x.id===id);if(!j||!confirm(`Permanently delete quote ${j.quoteNumber} and its connected contract, receipt, and photos?`))return;if(window.nikoDeleteRemoteFiles)await window.nikoDeleteRemoteFiles(j);state.jobs=state.jobs.filter(x=>x.id!==id);if(state.currentId===id)state.currentId=null;persist();renderDashboard();updateDocSelect();toast(`${j.quoteNumber} deleted`)}
function duplicateCurrent(){collectForm();const src=currentJob();if(!src)return;const n=nextNum(),copy=structuredClone(src);copy.id=crypto.randomUUID();copy.quoteNumber=`Q-${n}`;copy.contractNumber=`C-${n}`;copy.invoiceNumber=`I-${n}`;copy.status='Draft quote';copy.createdAt=copy.updatedAt=Date.now();['beforePhotos','afterPhotos','receiptPhotos'].forEach(key=>(copy[key]||[]).forEach(file=>{file.id=crypto.randomUUID();delete file.storagePath;delete file.cloudFileUnavailable}));state.counter++;state.jobs.unshift(copy);state.currentId=copy.id;persist();fillForm(copy);toast('Job duplicated')}
function updateDocSelect(){const s=$('#documentJobSelect'),old=s.value||state.currentId||'';s.innerHTML=state.jobs.length?state.jobs.map(j=>`<option value="${j.id}">${esc(j.customerName||'Unnamed')} — ${esc(j.quoteNumber)}</option>`).join(''):'<option value="">No saved jobs</option>';if(state.jobs.some(j=>j.id===old))s.value=old;renderPreview()}
function renderPreview(){const j=state.jobs.find(j=>j.id===$('#documentJobSelect').value);if(!j){$('#previewJobName').textContent='No job selected';$('#previewJobStatus').textContent='—';$('#previewSummary').innerHTML='';return}const t=totals(j);$('#previewJobName').textContent=j.customerName||j.quoteNumber;$('#previewJobStatus').textContent=j.status;$('#previewSummary').innerHTML=`<div><small>Project</small><strong>${esc(j.projectAddress||'—')}</strong></div><div><small>Quoted total</small><strong>${money(t.total)}</strong></div><div><small>Payments</small><strong>${money(j.paymentsReceived)}</strong></div><div><small>Balance</small><strong>${money(t.due)}</strong></div>`}
function brand(){const s=state.settings;return `<header class="print-brand"><div class="print-brand-main"><img class="print-brand-logo" src="assets/niko-logo.png" alt=""><div><h1>${esc(s.business)}</h1><p>Residential Repair · Improvement · Project Coordination</p></div></div><div class="print-contact">${esc(s.phone)}<br>${esc(s.email)}${s.address?`<br>${esc(s.address)}`:''}</div></header>`}
function foot(){const s=state.settings;return `<footer class="print-footer">${esc(s.business)} is operated by ${esc(s.legal)} · ${esc(s.phone)} · ${esc(s.email)}</footer>`}
function fields(arr){return `<div class="print-fields">${arr.map(([l,v])=>`<div class="print-field"><small>${esc(l)}</small><div>${esc(v||'')}</div></div>`).join('')}</div>`}
function signatures(){return `<div class="signature-grid"><div><div class="signature-line"></div><small>Customer signature and printed name · Date</small></div><div><div class="signature-line"></div><small>${esc(state.settings.legal)} authorized representative · Date</small></div></div>`}
function photoPermissionBlock(j){return `<div class="print-section">PROJECT PHOTO AUTHORIZATION</div><p><b>Selected permission:</b> ${esc(j.photoUsePermission||'Documentation only')}</p><p>The company may photograph areas reasonably related to the work for estimating, safety, documentation, quality control, warranty, insurance, payment, and dispute records. Public portfolio or marketing use requires the customer to select public non-identifying use. Faces, children, exact addresses, personal documents, access codes, security details, and other sensitive identifying information will not be intentionally published.</p><div class="terms-ack">☐ Documentation only &nbsp; ☐ Public non-identifying use approved &nbsp; ☐ Public use declined<br><br>Customer initials: __________ &nbsp; Company initials: __________ &nbsp; Date: __________</div>`}
function itemsTable(j,receipt=false){return `<table class="print-table"><thead><tr>${receipt?'<th>Done</th>':''}<th>Part</th><th>Description</th><th>Qty/Hrs</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${(j.items||[]).map((x,i)=>`<tr>${receipt?`<td>${x.done?'☒':'☐'}</td>`:''}<td>${i+1}</td><td>${esc(x.description)}</td><td>${esc(x.qty)}</td><td>${money(x.rate)}</td><td>${money((Number(x.qty)||0)*(Number(x.rate)||0))}</td></tr>`).join('')}</tbody></table>`}
function legalPage(title,page){return `<section class="print-page">${brand()}<div class="print-title"><h2>${title}</h2><span>${page}</span></div><div class="print-section">PROJECT TERMS AND CUSTOMER RESPONSIBILITIES</div><div class="legal-copy">${LEGAL.map(([h,b])=>`<p><b>${esc(h)}:</b> ${esc(b)}</p>`).join('')}<p><b>Estimate selection:</b> Before residential repair or service work begins, record the customer’s applicable estimate selection here: ☐ Written estimate &nbsp; ☐ Oral estimate &nbsp; ☐ No estimate requested, where permitted.</p></div><div class="terms-ack"><b>Customer acknowledgment:</b> I received this page, reviewed the written scope and price, had an opportunity to ask questions, and received any cancellation notice required for this transaction.<br><br>Customer initials: __________ &nbsp; Company initials: __________ &nbsp; Date: __________</div><p class="document-notice">Contract template only. Job-specific legal, licensing, permit, insurance, lien, and cancellation requirements must be confirmed before use.</p>${foot()}</section>`}
function photoPage(title,page,photos,label){const pics=[...(photos||[])];while(pics.length<4)pics.push(null);return `<section class="print-page">${brand()}<div class="print-title"><h2>${title}</h2><span>${page}</span></div><p>${label}</p><div class="print-photos">${pics.slice(0,4).map((p,i)=>`<div class="print-photo">${p&&p.type.startsWith('image/')?`<div><img src="${p.data}"><small>${esc(p.caption||p.name)}</small></div>`:`PHOTO ${i+1}<br>Area / view: __________________<br>Date: __________________`}</div>`).join('')}</div>${foot()}</section>`}
function coverPage(stage,title,number,date,j,totalPages,privateDocument=false){const s=state.settings,displayDate=dateLabel(date||j.createdAt||Date.now());return `<section class="print-cover"><div class="cover-top"><img class="cover-logo" src="assets/niko-logo.png" alt=""><div class="cover-company"><b>${esc(s.business)}</b><br>Operated by ${esc(s.legal)}<br>${esc(s.phone)} · ${esc(s.email)}</div></div><div class="cover-center"><span class="cover-stage">${esc(stage)}</span><h1>${esc(title)}</h1><div class="cover-number">${esc(number||'NUMBER PENDING')}</div><div class="cover-grid"><div class="cover-field"><small>Prepared for</small><strong>${esc(j.customerName||'Customer name pending')}</strong></div><div class="cover-field"><small>Document date</small><strong>${esc(displayDate)}</strong></div><div class="cover-field"><small>Project property</small><strong>${esc(j.projectAddress||'Project address pending')}</strong></div><div class="cover-field"><small>Prepared by</small><strong>${esc(s.business)}</strong></div></div>${privateDocument?'<div class="cover-private">PRIVATE COMPANY–FREELANCER AGREEMENT<br>Do not provide this document or its compensation terms to the customer.</div>':''}</div><div class="cover-bottom"><span>${esc(stage)} · ${esc(number||'')}</span><span>Page 1 of ${totalPages}</span></div></section>`}
function printDocument(type,j){if(!j){toast('Create or select a job first');return}const t=totals(j),common=fields([['Customer',j.customerName],['Phone',j.customerPhone],['Email',j.customerEmail],['Project',j.projectAddress]]);let html='';if(type==='quote'){html=`${coverPage('Pre-work document','Project Quote',j.quoteNumber,j.quoteDate,j,4)}<section class="print-page">${brand()}<div class="print-title"><h2>Project Quote</h2><span>Page 2 of 4</span></div>${fields([['Quote number',j.quoteNumber],['Contract number',j.contractNumber],['Invoice number',j.invoiceNumber],['Quote created',j.quoteDate]])}${common}<div class="print-section">PROPOSED WORK AND ITEMIZED PRICE</div><p>${esc(j.description||'No work description entered.')}</p>${itemsTable(j)}<div class="print-total"><div><span>Subtotal</span><b>${money(t.subtotal)}</b></div><div><span>Tax or other approved cost</span><b>${money(j.tax)}</b></div><div><span>Discount</span><b>${money(j.discount)}</b></div><div><span>Quoted total</span><b>${money(t.total)}</b></div></div>${fields([['Expected start',j.startDate],['Estimated completion',j.completionDate],['Quote valid through',j.validThrough],['Payment method',j.paymentMethod||'To be selected']])}<div class="print-section">RESPONSIBILITY SUMMARY</div><p><b>Materials:</b> ${esc(j.materials||'Not specified')} &nbsp; <b>Cleanup:</b> ${esc(j.cleanup||'Not specified')} &nbsp; <b>Permits:</b> ${esc(j.permitsBy||'Not specified')}</p><p>This quote covers only the written scope. Concealed conditions, customer changes, and added work require written documentation and may change price and schedule. The detailed terms on page 3 are incorporated into this quote.</p><div class="terms-ack"><b>Quote acceptance:</b> By signing, the customer approves the described scope and quoted price, acknowledges the material and cleanup selections, and confirms receipt of all four pages.</div>${signatures()}${foot()}</section>${legalPage('Project Quote','Page 3 of 4 · Terms')}${photoPage('Project Quote','Page 4 of 4 · Before Photos',j.beforePhotos,'Before-work condition record. Add captions identifying each area and any visible pre-existing condition.')}`}
if(type==='contract'){html=`${coverPage('Approved quote stage','Customer Contract',j.contractNumber,j.contractDate||j.quoteDate,j,4)}<section class="print-page">${brand()}<div class="print-title"><h2>Home Improvement Contract</h2><span>Page 2 of 4</span></div>${fields([['Contract number',j.contractNumber],['Approved quote',j.quoteNumber],['Invoice number',j.invoiceNumber],['Contract date',j.contractDate||j.quoteDate]])}${common}<div class="print-section">APPROVED SCOPE OF WORK</div><p>${esc(j.description||'No work description entered.')}</p>${itemsTable(j)}<div class="print-total"><div><span>Total customer contract price</span><b>${money(t.total)}</b></div><div><span>Deposit due</span><b>${money(j.deposit)}</b></div><div><span>Balance after deposit</span><b>${money(t.total-(Number(j.deposit)||0))}</b></div></div>${fields([['Expected start',j.startDate],['Estimated completion',j.completionDate],['Payment method',j.paymentMethod||'To be selected'],['Final payment terms',j.paymentDue]])}<div class="print-section">MATERIALS, CLEANUP, AND AUTHORIZATION</div><p><b>Materials:</b> ${esc(j.materials||'Not specified')} &nbsp; <b>Cleanup:</b> ${esc(j.cleanup||'Not specified')} &nbsp; <b>Permits:</b> ${esc(j.permitsBy||'Not specified')}</p><p>The customer authorizes the company to perform or coordinate the approved written work. No oral promise, added task, or allowance changes this agreement unless documented in writing.</p>${photoPermissionBlock(j)}${signatures()}${foot()}</section>${legalPage('Home Improvement Contract','Page 3 of 4 · Terms')}<section class="print-page">${brand()}<div class="print-title"><h2>Work Performer Authorization</h2><span>Page 4 of 4</span></div><div class="print-section">WHO WILL PERFORM THE WORK</div>${fields([['Work arrangement',j.workerType],['Legal name',j.workerName],['Company',j.workerCompany],['Contact',j.workerContact],['Trade assigned',j.workerTrade],['License if required',j.workerLicense],['Insurance confirmed',j.workerInsurance],['Work dates',`${j.startDate||''} — ${j.completionDate||''}`]])}<div class="print-section">RESPONSIBILITIES AND CUSTOMER ACKNOWLEDGMENT</div><p>The customer understands who is expected to perform the work and authorizes ${esc(state.settings.business)}, operated by ${esc(state.settings.legal)}, to coordinate the listed in-house worker or freelancer. The company may replace a worker when reasonably necessary. This authorization does not change the written customer price, scope, payment schedule, warranty, or duties imposed by law unless a signed change order says otherwise. Private company-to-freelancer compensation is not part of the customer agreement.</p><div class="terms-ack">Before work begins, confirm access instructions, utilities, pets, alarms, parking, areas requiring protection, permits, and any known hazards. Document all visible pre-existing damage with the quote photo record.</div>${signatures()}<div class="signature-grid"><div><div class="signature-line"></div><small>Worker or freelancer acknowledgment · Date</small></div></div>${foot()}</section>`}
if(type==='receipt'){html=`${coverPage('Completed work stage','Final Work Receipt',j.invoiceNumber,j.receiptDate||j.paymentDate||j.completionDate,j,5)}<section class="print-page">${brand()}<div class="print-title"><h2>Final Work Receipt</h2><span>Page 2 of 5</span></div>${fields([['Invoice number',j.invoiceNumber],['Quote number',j.quoteNumber],['Contract number',j.contractNumber],['Receipt date',j.receiptDate||j.paymentDate]])}${common}${fields([['First work date',j.startDate],['Completion date',j.completionDate],['Total work days',j.workDays],['Payment method',j.paymentMethod||'Not recorded']])}<div class="print-section">COMPLETED WORK CHECKLIST AND COST</div>${itemsTable(j,true)}<div class="print-total"><div><span>Labor</span><b>${money(j.laborTotal)}</b></div><div><span>Materials</span><b>${money(j.materialTotal)}</b></div><div><span>Other approved cost</span><b>${money(j.otherCost)}</b></div><div><span>Total customer invoice</span><b>${money(t.total)}</b></div><div><span>Payments received</span><b>${money(j.paymentsReceived)}</b></div><div><span>Balance due</span><b>${money(t.due)}</b></div></div><div class="print-section">DETAILED DESCRIPTION OF COMPLETED WORK</div><p>${esc(j.completedDescription||j.description||'No completion description entered.')}</p><div class="terms-ack"><b>60-day workmanship warranty:</b> Covered company-workmanship defects must be reported in writing within 60 calendar days after substantial completion. Review page 3 for exclusions and the inspection/correction process.</div>${signatures()}${foot()}</section>${legalPage('Final Work Receipt','Page 3 of 5 · Warranty and Terms')}${photoPage('Final Work Receipt','Page 4 of 5 · After Photos',j.afterPhotos,'After-work condition record. Captions should identify the completed area and date.')}<section class="print-page">${brand()}<div class="print-title"><h2>Material Receipt Attachments</h2><span>Page 5 of 5</span></div>${fields([['Invoice number',j.invoiceNumber],['Contract number',j.contractNumber],['Receipt copies',(j.receiptPhotos||[]).length],['Customer',j.customerName]])}<div class="print-section">MATERIALS AND PROJECT PURPOSE</div><p>${esc(j.completedDescription||j.description)}</p><p class="document-notice">Attached store receipts document material purchases. They do not replace the contract, prove payment by a particular party, or change the written material responsibility.</p><div class="receipt-space">${(j.receiptPhotos||[]).filter(p=>p.type.startsWith('image/')).slice(0,2).map(p=>`<div><img src="${p.data}" style="max-width:3.5in;max-height:3in"><br>${esc(p.caption||p.name)}</div>`).join('')||'ATTACH OR INSERT MATERIAL RECEIPT COPIES HERE'}</div>${foot()}</section>`}
if(type==='freelancer'){if(!j.freelancerName&&!j.freelancerCompany){toast('Add freelancer information first');return}html=`${coverPage('Private freelancer document','Freelancer Work Agreement',`F-${j.contractNumber||j.quoteNumber}`,j.freelancerStart||j.contractDate||j.quoteDate,j,3,true)}<section class="print-page">${brand()}<div class="print-title"><h2>Freelancer Work Agreement</h2><span>Page 2 of 3 · Private</span></div>${fields([['Related contract',j.contractNumber],['Freelancer',j.freelancerName],['Freelancer company',j.freelancerCompany],['Contact',j.freelancerContact],['Project property',j.projectAddress],['Assigned work',j.freelancerScope||j.workerTrade],['Start',j.freelancerStart||j.startDate],['Completion',j.freelancerCompletion||j.completionDate]])}<div class="print-section">PRIVATE COMPENSATION</div>${fields([['Company pays freelancer',money(j.freelancerPrice)],['Payment terms',j.freelancerPaymentTerms],['Documents status',j.freelancerDocuments],['Customer price','Confidential — not part of this agreement']])}<div class="print-section">ASSIGNED SCOPE</div><p>${esc(j.freelancerScope||j.workerTrade||j.description||'No freelancer scope entered.')}</p><p class="document-notice">Only the assigned freelancer scope is authorized. The freelancer has no authority to change the customer scope, quote a customer price, collect customer payment, or promise additional work unless Amr and Nhi LLC provides written authorization.</p><div class="signature-grid"><div><div class="signature-line"></div><small>Amr and Nhi LLC authorized representative · Date</small></div><div><div class="signature-line"></div><small>Freelancer legal signature and printed name · Date</small></div></div>${foot()}</section><section class="print-page">${brand()}<div class="print-title"><h2>Freelancer Terms</h2><span>Page 3 of 3 · Private</span></div><ol class="freelancer-terms"><li><b>Independent business relationship.</b> The parties intend the relationship stated here, but the actual facts and applicable law control worker classification. Nothing in this form guarantees independent-contractor treatment.</li><li><b>Scope and quality.</b> The freelancer will complete only the written assigned work in a professional and workmanlike manner, follow applicable codes and manufacturer instructions, and promptly report hidden or unsafe conditions.</li><li><b>No customer repricing.</b> Customer pricing, company margin, and company records are confidential. The freelancer will not discuss private compensation or independently change the customer’s price or scope.</li><li><b>Licensing and insurance.</b> The freelancer will maintain any legally required license, registration, insurance, or permit and provide requested proof before beginning regulated work.</li><li><b>Tools, taxes, and expenses.</b> Unless the written scope says otherwise, the freelancer provides necessary ordinary tools and is responsible for the freelancer’s own taxes and business expenses, subject to applicable law.</li><li><b>Safety and property.</b> The freelancer will use reasonable care, follow site safety requirements, protect customer property, and immediately report injury, damage, or a hazardous condition.</li><li><b>Payment.</b> Compensation is limited to the private amount written on page 2 plus written company-approved changes. Payment may be withheld for incomplete, defective, undocumented, or unauthorized work to the extent permitted by law.</li><li><b>Warranty cooperation.</b> The freelancer will reasonably assist with inspection and correction of covered defects caused by the freelancer’s work during the company’s applicable customer warranty period.</li><li><b>No delegation.</b> The freelancer may not send another worker or subcontract the assignment without prior written company approval.</li><li><b>Records and confidentiality.</b> Photos, customer details, access information, pricing, and documents may be used only to perform the assigned work and must not be publicly shared without written permission.</li><li><b>Entire agreement.</b> This document and signed written changes are the agreement for the assigned work. Ohio law applies, and nonwaivable legal rights remain in effect.</li></ol><div class="terms-ack"><b>Private agreement acknowledgment:</b> Both parties reviewed the assigned scope, compensation, schedule, documentation, safety, and customer-confidentiality requirements.</div><div class="signature-grid"><div><div class="signature-line"></div><small>Company initials · Date</small></div><div><div class="signature-line"></div><small>Freelancer initials · Date</small></div></div>${foot()}</section>`}
$('#printArea').innerHTML=html;setTimeout(()=>window.print(),150)}
function printPolicies(){const html=`<section class="print-page policy-print-page">${brand()}<div class="print-title"><h2>Business Terms — Plain-Language Summary</h2><span>Reference copy</span></div><p>This summary helps customers understand the standard project terms. The signed quote, contract, change orders, and required statutory notices control.</p><div class="legal-copy">${LEGAL.map(([h,b])=>`<p><b>${esc(h)}:</b> ${esc(b)}</p>`).join('')}</div><div class="terms-ack"><b>Legal review reminder:</b> This template does not determine whether a particular job is subject to home-solicitation, home-construction, licensing, permit, lien, insurance, or other requirements.</div>${foot()}</section>`;$('#printArea').innerHTML=html;setTimeout(()=>window.print(),120)}
function hydrateSettings(){const s=state.settings;$('#settingBusiness').value=s.business;$('#settingLegal').value=s.legal;$('#settingPhone').value=s.phone;$('#settingEmail').value=s.email;$('#settingAddress').value=s.address||'';if($('#settingWebsite'))$('#settingWebsite').value=s.website||'https://nikoresidentialholdings.com'}
function saveSettings(){state.settings={business:$('#settingBusiness').value,legal:$('#settingLegal').value,phone:$('#settingPhone').value,email:$('#settingEmail').value,address:$('#settingAddress').value,website:$('#settingWebsite')?.value||'https://nikoresidentialholdings.com'};persist();toast('Company information saved')}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`niko-project-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup downloaded')}
async function importData(file){try{const data=JSON.parse(await file.text());if(!Array.isArray(data.jobs)||!data.settings)throw new Error();if(!confirm(`Restore ${data.jobs.length} jobs? This replaces current local data.`))return;state=data;await persist();hydrateSettings();renderDashboard();updateDocSelect();switchView('dashboard');toast('Backup restored')}catch{toast('That backup file is not valid')}}
async function resetApp(){if(!confirm('Permanently erase every job, photo, and setting from this account and device? This cannot be undone.'))return;const jobs=[...state.jobs];if(window.nikoDeleteRemoteFiles)for(const job of jobs)await window.nikoDeleteRemoteFiles(job);state={jobs:[],settings:{business:'Niko Residential Holdings',legal:'Amr and Nhi LLC',phone:'513-212-5883',email:'daraghmehamr1@gmail.com',address:'',website:'https://nikoresidentialholdings.com'},counter:1,currentId:null};await persist();hydrateSettings();renderDashboard();updateDocSelect();switchView('dashboard');toast('Account data erased')}
function registerWebMCP(){const c=document.modelContext;if(!c?.registerTool)return;const fail=m=>{throw new Error(m)};c.registerTool({name:'list_jobs',title:'List saved jobs',description:'List project records currently saved in the visible Niko Project Manager.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({jobs:state.jobs.map(j=>({id:j.id,customer:j.customerName,status:j.status,quoteNumber:j.quoteNumber,total:totals(j).total}))})});c.registerTool({name:'create_job_draft',title:'Create job draft',description:'Create a new local job draft with customer name and project address.',inputSchema:{type:'object',properties:{customerName:{type:'string'},projectAddress:{type:'string'}},required:['customerName','projectAddress'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input?.customerName?.trim()||!input?.projectAddress?.trim())fail('Customer name and project address are required');const j=blankJob();j.customerName=input.customerName.trim();j.projectAddress=input.projectAddress.trim();state.jobs.unshift(j);state.counter++;state.currentId=j.id;await persist();renderDashboard();return{id:j.id,quoteNumber:j.quoteNumber,status:j.status}}});}
$$('.nav-btn').forEach(b=>b.onclick=()=>switchView(b.dataset.view));$('.mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');['#newJobTop','#newJobHero','#newJobEmpty'].forEach(s=>$(s).onclick=createJob);$('#jobSearch').oninput=e=>renderDashboard(e.target.value);$$('.step').forEach(b=>b.onclick=()=>setStep(Number(b.dataset.step)));$('#prevStep').onclick=()=>setStep(activeStep-1);$('#nextStep').onclick=()=>{collectForm();autosave();if(activeStep===5){switchView('documents');updateDocSelect()}else setStep(activeStep+1)};$('#saveJob').onclick=async()=>{collectForm();await persist();renderDashboard();toast('Job saved')};$('#jobForm').addEventListener('input',e=>{if(e.target.matches('[data-f],input[name=tax],input[name=discount],input[name=freelancerPrice]'))calcTotals();autosave()});$('#addItem').onclick=addItem;$('#deleteJob').onclick=deleteCurrent;$('#duplicateJob').onclick=duplicateCurrent;$('#beforePhotos').onchange=e=>filesToPhotos(e.target.files,'beforePhotos');$('#afterPhotos').onchange=e=>filesToPhotos(e.target.files,'afterPhotos');$('#receiptPhotos').onchange=e=>filesToPhotos(e.target.files,'receiptPhotos');$('#documentJobSelect').onchange=renderPreview;$$('.print-doc').forEach(b=>b.onclick=()=>printDocument(b.dataset.doc,state.jobs.find(j=>j.id===$('#documentJobSelect').value)));$('#saveSettings').onclick=saveSettings;$('#exportData').onclick=exportData;$('#importData').onchange=e=>importData(e.target.files[0]);$('#resetApp').onclick=resetApp;
$('#printPolicySummary').onclick=printPolicies;
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(console.error);window.nikoAppReady=loadState().then(registerWebMCP);

// 2026 workflow upgrade: reusable unused numbers, categorized charges, completed work, and customer history.
function renderDashboard(filter=''){
  const jobs=state.jobs.filter(j=>[j.customerName,j.projectAddress,j.quoteNumber,j.contractNumber,j.invoiceNumber].join(' ').toLowerCase().includes(filter.toLowerCase()));
  const completed=state.jobs.filter(j=>['Completed','Paid'].includes(j.status));
  $('#statJobs').textContent=state.jobs.length;
  $('#statOpen').textContent=state.jobs.filter(j=>!['Completed','Paid'].includes(j.status)).length;
  $('#statValue').textContent=money(state.jobs.reduce((s,j)=>s+totals(j).total,0));
  $('#statDue').textContent=money(state.jobs.reduce((s,j)=>s+Math.max(0,totals(j).due),0));
  $('#statCompletedRevenue').textContent=money(completed.reduce((s,j)=>s+totals(j).finalTotal,0));
  $('#statCollected').textContent=money(completed.reduce((s,j)=>s+(Number(j.paymentsReceived)||0),0));
  $('#nextNumber').textContent=nextNum();
  const list=$('#jobList');
  list.innerHTML=jobs.map(j=>`<div class="job-row"><div><b>${esc(j.customerName||'Unnamed customer')}</b><small>${esc(j.projectAddress||'No project address')}</small></div><div><b>${esc(j.quoteNumber)}</b><small>${new Date(j.updatedAt).toLocaleDateString()}</small></div><span class="status-chip">${esc(j.status)}</span><div><b>${money(totals(j).finalTotal)}</b><small>${money(totals(j).due)} due</small></div><button class="open-job" data-id="${j.id}" aria-label="Open job">›</button><button class="job-delete" data-id="${j.id}" aria-label="Delete job">×</button></div>`).join('');
  $('#emptyJobs').classList.toggle('hidden',state.jobs.length>0);
  $$('.open-job').forEach(b=>b.onclick=()=>openJob(b.dataset.id));
  $$('.job-delete').forEach(b=>b.onclick=()=>deleteJobById(b.dataset.id));
  renderCompleted(); renderCustomers($('#customerSearch')?.value||'');
}
function switchView(name){
  $$('.view').forEach(v=>v.classList.remove('active')); $(`#${name}View`)?.classList.add('active');
  $$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  $('#viewTitle').textContent={dashboard:'Project dashboard',editor:'Job workspace',leads:'Quote requests',completed:'Completed work',customers:'Customers',schedule:'Schedule',publicProjects:'Public projects',documents:'Print center',policies:'Policies and terms',settings:'Settings'}[name]||'Niko Project Manager';
  $('.sidebar').classList.remove('open');
  if(name==='documents'){updateDocSelect();renderPreview()} if(name==='completed')renderCompleted(); if(name==='customers')renderCustomers($('#customerSearch')?.value||'');
  if(window.nikoPortalView)window.nikoPortalView(name);
}
function collectForm(){
  const j=currentJob(); if(!j)return null; const fd=new FormData($('#jobForm'));
  for(const [k,v] of fd.entries())if(!['beforePhotos','afterPhotos','receiptPhotos'].includes(k))j[k]=v;
  j.updatedAt=Date.now();
  j.items=$$('.line-item').map(r=>({id:r.dataset.id,done:$('[data-f="done"]',r).checked,category:$('[data-f="category"]',r)?.value||'Labor',description:$('[data-f="description"]',r).value,qty:$('[data-f="qty"]',r).value,rate:$('[data-f="rate"]',r).value}));
  $('#jobHeading').textContent=j.customerName||'New project'; $('#jobNumbers').textContent=`${j.quoteNumber} · ${j.contractNumber} · ${j.invoiceNumber}`; $('#jobStatusBadge').textContent=j.status; return j;
}
function renderItems(j){
  $('#lineItems').innerHTML=(j.items||[]).map(x=>`<div class="line-item categorized" data-id="${x.id}"><input data-f="done" type="checkbox" ${x.done?'checked':''} aria-label="Completed"><select data-f="category" aria-label="Charge type"><option ${(x.category||'Labor')==='Labor'?'selected':''}>Labor</option><option ${x.category==='Material'?'selected':''}>Material</option></select><input data-f="description" value="${esc(x.description)}" placeholder="Describe the charge"><input data-f="qty" type="number" step="0.01" value="${esc(x.qty)}"><input data-f="rate" type="number" step="0.01" value="${esc(x.rate)}"><strong data-amount>${money((Number(x.qty)||0)*(Number(x.rate)||0))}</strong><button type="button" class="remove-item" aria-label="Remove item">×</button></div>`).join('');
  $$('.remove-item').forEach(b=>b.onclick=()=>{b.closest('.line-item').remove();calcTotals();autosave()});
}
function addItem(){const j=currentJob();collectForm();j.items.push({id:crypto.randomUUID(),done:false,category:'Labor',description:'',qty:1,rate:0});renderItems(j);autosave()}
function calcTotals(){
  let sub=0,labor=0,materials=0; $$('.line-item').forEach(r=>{const amount=(Number($('[data-f="qty"]',r).value)||0)*(Number($('[data-f="rate"]',r).value)||0);$('[data-amount]',r).textContent=money(amount);sub+=amount;if(($('[data-f="category"]',r)?.value||'Labor')==='Material')materials+=amount;else labor+=amount});
  $('#laborSubtotal').textContent=money(labor); $('#materialSubtotal').textContent=money(materials); const total=sub+(Number($('#jobForm').elements.tax.value)||0)-(Number($('#jobForm').elements.discount.value)||0),freelancer=Number($('#jobForm').elements.freelancerPrice?.value)||0; $('#subtotal').textContent=money(sub);$('#grandTotal').textContent=money(total);if($('#customerContractTotal'))$('#customerContractTotal').textContent=money(total);if($('#freelancerCostTotal'))$('#freelancerCostTotal').textContent=money(freelancer);if($('#grossDifference'))$('#grossDifference').textContent=money(total-freelancer);
}
async function removeJob(j){
  if(window.nikoDeleteRemoteFiles)await window.nikoDeleteRemoteFiles(j);
  if(['Completed','Paid'].includes(j.status)){state.retiredNumbers=state.retiredNumbers||[];const n=jobNumber(j);if(n&&!state.retiredNumbers.includes(n))state.retiredNumbers.push(n)}
  state.jobs=state.jobs.filter(x=>x.id!==j.id);if(state.currentId===j.id)state.currentId=null;nextNumberValue();await persist();renderDashboard();updateDocSelect();
}
async function deleteCurrent(){const j=currentJob();if(!j||!confirm(`Delete ${j.customerName||j.quoteNumber}? Unfinished quote numbers may be reused; completed numbers remain retired.`))return;await removeJob(j);switchView('dashboard');toast('Job deleted')}
async function deleteJobById(id){const j=state.jobs.find(x=>x.id===id);if(!j||!confirm(`Permanently delete ${j.quoteNumber}? Unfinished quote numbers may be reused; completed numbers remain retired.`))return;await removeJob(j);toast(`${j.quoteNumber} deleted`)}
function renderCompleted(){
  const jobs=state.jobs.filter(j=>['Completed','Paid'].includes(j.status)).sort((a,b)=>new Date(b.completionDate||b.updatedAt)-new Date(a.completionDate||a.updatedAt));
  if(!$('#completedList'))return; $('#completedCount').textContent=jobs.length;$('#completedRevenue').textContent=money(jobs.reduce((s,j)=>s+totals(j).finalTotal,0));$('#completedCollected').textContent=money(jobs.reduce((s,j)=>s+(Number(j.paymentsReceived)||0),0));$('#completedDue').textContent=money(jobs.reduce((s,j)=>s+Math.max(0,totals(j).due),0));
  $('#completedList').innerHTML=jobs.length?jobs.map(j=>`<article class="portal-card"><div class="portal-card-head"><div><h3>${esc(j.customerName||'Unnamed customer')}</h3><small>${esc(j.invoiceNumber)} · ${dateLabel(j.completionDate||j.receiptDate)}</small></div><span class="status-chip">${esc(j.status)}</span></div><p>${esc(j.completedDescription||j.description||'No completion description')}</p><div class="lead-meta"><div><small>Labor</small><strong>${money(totals(j).receiptLabor)}</strong></div><div><small>Materials</small><strong>${money(totals(j).receiptMaterials)}</strong></div><div><small>Total</small><strong>${money(totals(j).finalTotal)}</strong></div><div><small>Balance</small><strong>${money(totals(j).due)}</strong></div></div><div class="portal-card-actions"><button type="button" class="open-completed" data-id="${j.id}">Open job</button></div></article>`).join(''):'<div class="portal-empty">No completed work yet. Mark a job Completed or Paid to move it here.</div>';
  $$('.open-completed').forEach(b=>b.onclick=()=>openJob(b.dataset.id));
}
function renderCustomers(filter=''){
  if(!$('#customerList'))return;const groups=new Map();state.jobs.forEach(j=>{const key=(j.customerEmail||j.customerPhone||j.customerName||j.id).toLowerCase();if(!groups.has(key))groups.set(key,[]);groups.get(key).push(j)});
  const cards=[...groups.values()].filter(js=>js.some(j=>[j.customerName,j.customerPhone,j.customerEmail,j.projectAddress].join(' ').toLowerCase().includes(filter.toLowerCase()))).sort((a,b)=>(a[0].customerName||'').localeCompare(b[0].customerName||''));
  $('#customerList').innerHTML=cards.length?cards.map(js=>{const c=js[0],completed=js.filter(j=>['Completed','Paid'].includes(j.status));return `<article class="portal-card"><div class="portal-card-head"><div><h3>${esc(c.customerName||'Unnamed customer')}</h3><small>${esc(c.customerPhone||'No phone')} · ${esc(c.customerEmail||'No email')}</small></div><span class="status-chip">${js.length} job${js.length===1?'':'s'}</span></div><div class="lead-meta"><div><small>Total work</small><strong>${money(js.reduce((s,j)=>s+totals(j).finalTotal,0))}</strong></div><div><small>Completed</small><strong>${completed.length}</strong></div><div><small>Collected</small><strong>${money(js.reduce((s,j)=>s+(Number(j.paymentsReceived)||0),0))}</strong></div></div>${js.map(j=>`<button type="button" class="customer-job" data-id="${j.id}">${esc(j.quoteNumber)} · ${esc(j.status)} · ${esc(j.projectAddress||'No address')}</button>`).join('')}</article>`}).join(''):'<div class="portal-empty">No matching customers.</div>';
  $$('.customer-job').forEach(b=>b.onclick=()=>openJob(b.dataset.id));
}
$('#customerSearch')?.addEventListener('input',e=>renderCustomers(e.target.value));
